'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var absf = require( '@stdlib/math/base/special/absf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var EPS = require( '@stdlib/constants/float32/eps' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var erfcf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
    'skip': ( erfcf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
    t.ok( true, __filename );
    t.strictEqual( typeof erfcf, 'function', 'main export is a function' );
    t.end();
});

tape( 'the function returns `1.0` if provided `0`', opts, function test( t ) {
    var y = erfcf( 0.0 );
    t.strictEqual( y, 1.0, 'returns 1.0' );
    t.end();
});

tape( 'the function returns `0.0` if provided `+infinity`', opts, function test( t ) {
    var y = erfcf( PINF );
    t.strictEqual( y, 0.0, 'returns 0.0' );
    t.end();
});

tape( 'the function returns `2.0` if provided `-infinity`', opts, function test( t ) {
    var y = erfcf( NINF );
    t.strictEqual( y, 2.0, 'returns 2.0' );
    t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', opts, function test( t ) {
    var y = erfcf( NaN );
    t.strictEqual( isnanf( y ), true, 'returns NaN' );
    t.end();
});

tape( 'the function evaluates the complementary error function (positive values)', opts, function test( t ) {
    var delta;
    var tol;
    var x;
    var y;
    var e;

    x = f32( 0.5 );
    y = erfcf( x );
    e = f32( 0.4795001221656799 );
    delta = absf( y - e );
    tol = f32( 2.0 * EPS * absf( e ) );
    t.strictEqual( delta <= tol, true, 'within tolerance. x: '+x+'. y: '+y+'. E: '+e+'. tol: '+tol+'. delta: '+delta+'.' );

    x = f32( 1.0 );
    y = erfcf( x );
    e = f32( 0.1572992056817412 );
    delta = absf( y - e );
    tol = f32( 2.0 * EPS * absf( e ) );
    t.strictEqual( delta <= tol, true, 'within tolerance. x: '+x+'. y: '+y+'. E: '+e+'. tol: '+tol+'. delta: '+delta+'.' );

    x = f32( 2.0 );
    y = erfcf( x );
    e = f32( 0.004677734714001417 );
    delta = absf( y - e );
    tol = f32( 5.0 * EPS * absf( e ) );
    t.strictEqual( delta <= tol, true, 'within tolerance. x: '+x+'. y: '+y+'. E: '+e+'. tol: '+tol+'. delta: '+delta+'.' );

    t.end();
});

tape( 'the function evaluates the complementary error function (negative values)', opts, function test( t ) {
    var delta;
    var tol;
    var x;
    var y;
    var e;

    x = f32( -0.5 );
    y = erfcf( x );
    e = f32( 1.5204998778343201 );
    delta = absf( y - e );
    tol = f32( 2.0 * EPS * absf( e ) );
    t.strictEqual( delta <= tol, true, 'within tolerance. x: '+x+'. y: '+y+'. E: '+e+'. tol: '+tol+'. delta: '+delta+'.' );

    x = f32( -1.0 );
    y = erfcf( x );
    e = f32( 1.8427007943182588 );
    delta = absf( y - e );
    tol = f32( 2.0 * EPS * absf( e ) );
    t.strictEqual( delta <= tol, true, 'within tolerance. x: '+x+'. y: '+y+'. E: '+e+'. tol: '+tol+'. delta: '+delta+'.' );

    t.end();
});

tape( 'the function evaluates the complementary error function (large positive values)', opts, function test( t ) {
    var x;
    var y;

    x = f32( 10.0 );
    y = erfcf( x );
    t.strictEqual( y, 0.0, 'returns 0.0' );

    t.end();
});

tape( 'the function evaluates the complementary error function (large negative values)', opts, function test( t ) {
    var x;
    var y;

    x = f32( -10.0 );
    y = erfcf( x );
    t.strictEqual( y, 2.0, 'returns 2.0' );

    t.end();
});